function backupLabel(){const days=backupAgeDays(state);if(days===null)return 'No backup yet on this device.';try{const when=new Date(state.lastBackupAt).toLocaleDateString('en-ZA',{day:'numeric',month:'short',year:'numeric'})}catch{return 'Backup timestamp unavailable.'}return days===0?`Last backup: just now (${when})`:`Last backup: ${days} day${days===1?'':'s'} ago (${when})`}
