async function businessDialog(){const keys=['live','business-2','business-3','business-4','business-5'],records=await Promise.all(keys.map(load));modalForm('Your businesses',`<p class="form-note">Five separate device workspaces. Export a backup for each business. Demo data remains separate. The selected business is remembered on this device.</p><div class="field"><label for="business-slot">Business workspace</label><select id="business-slot" name="key">${keys.map((key,n)=>`<option value="${key}" ${mode===key?'selected':''}>${n+1}. ${esc(records[n]?.business?.name||'Empty workspace')}</option>`).join('')}</select></div>`,async f=>{if(working||switching)throw Error('Wait for the current save.');const target=f.get('key');if(!keys.includes(target))throw Error('Invalid workspace.');if(target===mode){modal.close();return}switching=true;const previousMode=mode,previousState=state;try{const incoming=await load(target)||emptyState();validateState(incoming);clearDraftFor(mode,!!route.quote,route.id);mode=target;state=incoming;returnMode=target;try{localStorage.setItem('invoiceflow-business',target)}catch{}modal.close();route={page:'overview'};editLines=[];render();toast('Business workspace opened.')}catch(e){mode=previousMode;state=previousState;throw e}finally{switching=false}},'Open business')}
function encryptedBackupDialog(){modalForm('Encrypt your backup',`<p class="form-note">AES-256-GCM encryption with a password-derived key. Choose a password of at least 12 characters and keep it safe. Lost passwords cannot be recovered. This encrypts the downloaded backup; device records remain unencrypted.</p><div class="field"><label for="backup-password">Backup password</label><input id="backup-password" name="password" type="password" minlength="12" required autocomplete="new-password"></div><div class="field"><label for="backup-confirm">Confirm password</label><input id="backup-confirm" name="confirm" type="password" minlength="12" required autocomplete="new-password"></div>`,async f=>{if(f.get('password')!==f.get('confirm'))throw Error('Passwords do not match.');await commit(s=>{s.lastBackupAt=new Date().toISOString()});const encrypted=await encryptBackup(makeBackup(state,mode),f.get('password'));download(encrypted,`invoiceflow-${mode}-encrypted-${today()}.json`);modal.close();render();toast('Encrypted backup download started.')},'Download encrypted backup')}
async function bankImportDialog(){modalForm('Match incoming bank payments',`<p class="form-note">Paste incoming transactions only, using date,reference,amount. Amounts are positive rand. No bank connection or automatic reconciliation. Each candidate must be reviewed before it becomes a payment.</p><div class="field"><label for="bank-csv">Bank CSV</label><textarea id="bank-csv" name="csv" rows="8" required placeholder="date,reference,amount"></textarea></div>`,async f=>{if(!globalThis.crypto?.subtle)throw Error('Bank matching needs HTTPS. Open the secure production app.');const rows=bankRows(f.get('csv'));const enriched=await Promise.all(rows.map(async row=>{const encoded=new TextEncoder().encode(JSON.stringify([row.date,row.reference.toLowerCase(),row.amount])),hash=[...new Uint8Array(await crypto.subtle.digest('SHA-256',encoded))].map(b=>b.toString(16).padStart(2,'0')).join('');return {...row,hash}}));modal.close();reviewBankRows(enriched)},'Review matches')}
function reviewBankRows(rows){const available=rows.filter(row=>!state.invoices.some(i=>i.payments.some(p=>p.bankFingerprint===row.hash)));modalForm('Review bank matches',`<p class="form-note">${rows.length-available.length} previously recorded rows excluded. Identical date, reference and amount are treated as one transaction; genuine duplicates can be recorded manually. Choose an invoice for each payment to record; leave unmatched rows on Skip.</p>${available.map((row,n)=>{const options=state.invoices.filter(i=>i.state==='issued'&&i.date<=row.date&&balance(i)>=row.amount),matched=options.filter(i=>row.reference.toUpperCase().includes(i.number));return `<div class="field"><label for="bank-row-${n}">${date(row.date)} · ${esc(row.reference)} · ${money(row.amount)}</label><select id="bank-row-${n}" name="row-${n}"><option value="">Skip this row</option>${options.map(i=>`<option value="${i.id}" ${matched.length===1&&matched[0].id===i.id?'selected':''}>${esc(i.number)} · ${esc(i.customer.name)} · ${money(balance(i))} due</option>`).join('')}</select></div>`}).join('')}`,async f=>{const selected=available.map((row,n)=>({row,invoiceId:f.get('row-'+n)})).filter(v=>v.invoiceId);if(!selected.length)throw Error('Choose at least one invoice, or Cancel.');await commit(s=>{const seen=new Set();for(const {row,invoiceId} of selected){if(seen.has(row.hash))continue;recordBankPayment(s,invoiceId,{date:row.date,amount:row.amount,reference:row.reference},row.hash);seen.add(row.hash)}});modal.close();render();toast('Reviewed bank payments recorded.')},'Record selected payments')}
function previewDocument(){const form=$('#invoice-form');if(!form.reportValidity())return;const f=new FormData(form),temp=structuredClone(state);const invoiceId=(route.quote?saveQuote:createInvoice)(temp,{id:route.id,customerId:f.get('customerId'),date:f.get('date'),due:f.get('due'),notes:f.get('notes'),lines:readLines(),discount:cents(f.get('discount')||'0'),deposit:cents(f.get('deposit')||'0'),template:f.get('template'),...taxFields(f.get('tax'))});validateState(temp);const invoice=(route.quote?temp.quotes:temp.invoices).find(i=>i.id===invoiceId);modalForm('Document preview · unsaved',invoiceDocument({...invoice,kind:route.quote?'quote':undefined}),async()=>{modal.close()},'Back to editor')}
Object.assign(actions,{businesses:async()=>{if(route.page==='editor'&&!await confirmUnsaved({title:'Switch business?',body:'Your draft is saved on this device and will be here when you return.',confirmLabel:'Switch',cancelLabel:'Stay'}))return;return businessDialog()},'secure-backup':encryptedBackupDialog,'bank-import':bankImportDialog,'preview-document':previewDocument,install:async()=>{if(globalThis.AppHost){toast('InvoiceFlow is already installed.');return}if(installPrompt){await installPrompt.prompt();installPrompt=null;return}modalForm('Install InvoiceFlow',`<p>On Android Chrome, open the browser menu and choose <strong>Install app</strong> or <strong>Add to Home screen</strong>. On iPhone/iPad Safari, use <strong>Share → Add to Home Screen</strong>.</p><p class="form-note">A first online visit is needed to cache app files. Keep backups even when installed. This browser may already have the app installed or may not support installation.</p>`,async()=>modal.close(),'Done')}});

function offerUpdate(registration){if(!registration||!registration.waiting)return;const existing=$('#apply-update');if(existing)return;const button=document.createElement('button');button.id='apply-update';button.className='btn small';button.textContent='Apply app update';button.onclick=async()=>{if(route.page==='editor'&&!await confirmUnsaved({title:'Apply update?',body:'The app will reload. Your records are not affected.',confirmLabel:'Apply update',cancelLabel:'Stay'}))return;const worker=registration.waiting;if(!worker)return;let reloaded=false;navigator.serviceWorker.addEventListener('controllerchange',()=>{if(!reloaded){reloaded=true;location.reload()}});worker.postMessage({type:'SKIP_WAITING'})};$('.side-bottom')?.prepend(button)}
